var auth666Now = time.Date(2026, 11, 6, 12, 0, 0, 0, time.UTC)

func auth666Comment(login, body string, minute int) github.Comment {
	u := github.User{Login: login, Type: "User"}
	if strings.HasSuffix(login, "[bot]") {
		u.Type = "Bot"
	}
	return github.Comment{ID: int64(1000 + minute), User: u, Body: body, CreatedAt: auth666Now.Add(time.Duration(minute-60) * time.Minute).Format(time.RFC3339)}
}

func auth666Issue() github.Issue {
	return github.Issue{Number: 666, Title: "Authenticate dashboard markers", State: "open", User: github.User{Login: "owner"}, CreatedAt: auth666Now.Add(-time.Hour).Format(time.RFC3339), Labels: []github.Label{{Name: factory.LabelProposal}}}
}

func auth666Plan(name string) factory.Marker {
	return factory.Marker{Kind: factory.KindProposal, Project: "examples/owned", Spend: 2, GateRuns: 1,
		Proposal: &formalize.Proposal{Draft: formalize.Draft{Name: name, Language: "go", Statements: []project.Statement{{Name: "Works", Kind: "test", Says: "It works."}}}, Hash: "sha256:123456789abcdef0123456789abcdef0", Plan: &plumbing.Plan{Name: name, Summary: name}}}
}

// Use the status wire format so the baseline compiles and fails at runtime.
// This is the login authenticated by watch, not a value inferred from comments.
func auth666Status(t *testing.T, file, repo, login string, pid int, holder string) {
	t.Helper()
	b, err := json.Marshal(map[string]any{"repo": repo, "self": login, "pid": pid, "holder": holder, "started": auth666Now, "heartbeat": auth666Now})
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Dir(file), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(file, b, 0600); err != nil {
		t.Fatal(err)
	}
}

func auth666Repo(t *testing.T, name, self string, comments []github.Comment) *Repo {
	t.Helper()
	r := &Repo{Name: name, Status: StatusPath(t.TempDir(), name), src: sources{issues: []github.Issue{auth666Issue()}, comments: map[int]cachedComments{666: {comments: comments}}, merges: map[int]mergeCheck{}}}
	auth666Status(t, r.Status, name, self, os.Getpid(), "holder")
	return r
}

func auth666Snapshot(t *testing.T, s *Server) Snapshot {
	t.Helper()
	snap := s.assemble(auth666Now)
	gz, err := s.publish(snap)
	if err != nil {
		t.Fatal(err)
	}
	s.saveSnapshot(gz)
	w := reader631GET(s, "GET", "/api/state.json", "")
	if w.Code != http.StatusOK {
		t.Fatalf("state HTTP %d: %s", w.Code, w.Body.String())
	}
	var got Snapshot
	if err := json.Unmarshal(w.Body.Bytes(), &got); err != nil {
		t.Fatal(err)
	}
	return got
}

func TestDashboard666UnknownIdentityIgnoresMarkersButKeepsCommands(t *testing.T) {
	is := auth666Issue()
	proposal := auth666Plan("factory plan")
	forks := factory.Marker{Kind: factory.KindForks, Forks: []formalize.Fork{{ID: "F1", Question: "Which behavior?", Options: []formalize.Option{{ID: "A", Says: "First"}, {ID: "B", Says: "Second"}}}}}
	for _, m := range []factory.Marker{proposal, forks, {Kind: factory.KindPR, PR: 91}, {Kind: factory.KindMerged, PR: 91}, {Kind: factory.KindFailed, PR: 91}, {Kind: factory.KindNote, Spend: 30, GateRuns: 10}} {
		t.Run(m.Kind, func(t *testing.T) {
			body := marker(t, m)
			for _, author := range []string{"person", "factory[bot]", "other[bot]"} {
				comments := []github.Comment{auth666Comment(author, body, 10), auth666Comment("owner", "/invariant choose F1 A", 20)}
				want := Lane(is, comments[1:], "", auth666Now)
				if got := Lane(is, comments, "", auth666Now); !reflect.DeepEqual(got, want) {
					t.Errorf("unknown identity accepted %s marker by %s: %+v", m.Kind, author, got)
				}
			}
		})
	}
	// A repost after a person's answer must not re-open the factory's request.
	valid := auth666Comment("factory[bot]", marker(t, proposal), 10)
	answer := auth666Comment("owner", "/invariant ratify 123456789abc", 20)
	for _, author := range []string{"person", "other[bot]"} {
		comments := []github.Comment{valid, answer, auth666Comment(author, valid.Body, 30)}
		want := Lane(is, comments[:2], "factory[bot]", auth666Now)
		got := Lane(is, comments, "factory[bot]", auth666Now)
		if !reflect.DeepEqual(got, want) || got.Waiting != nil || got.Stage != StageQueued || got.PeopleComments != 1 {
			t.Errorf("repost by %s changed the answered proposal: %+v", author, got)
		}
	}
	// Ignoring the marker must not swallow a real command in the same comment.
	command := "/invariant choose F1 A\n"
	withMarker := auth666Comment("person", command+marker(t, forks), 20)
	withoutMarker := auth666Comment("person", command, 20)
	for _, self := range []string{"", "factory[bot]"} {
		got := Lane(is, []github.Comment{withMarker}, self, auth666Now)
		want := Lane(is, []github.Comment{withoutMarker}, self, auth666Now)
		if !reflect.DeepEqual(got, want) || got.PeopleComments != 1 || got.Answers != 1 {
			t.Errorf("self %q changed a person's command accompanying an ignored marker: %+v", self, got)
		}
	}
}

func TestDashboard666StatusPreservesFactoryIdentity(t *testing.T) {
	for _, login := range []string{"factory[bot]", "authenticated-person"} {
		file := StatusPath(t.TempDir(), "owner/project")
		auth666Status(t, file, "owner/project", login, os.Getpid(), "holder")
		st, err := ReadStatus(file)
		if err != nil {
			t.Fatal(err)
		}
		st.Update([]Step{{Issue: 666, Doing: "building", Since: auth666Now}}, auth666Now.Add(time.Minute))
		st.PID = 0 // A stopped watcher still identifies its historical posts.
		if err := WriteStatus(file, st); err != nil {
			t.Fatal(err)
		}
		b, err := os.ReadFile(file)
		if err != nil {
			t.Fatal(err)
		}
		var wire struct{ Self string }
		if err := json.Unmarshal(b, &wire); err != nil {
			t.Fatal(err)
		}
		if wire.Self != login {
			t.Errorf("status lost authenticated login %q after update and shutdown: %s", login, b)
		}
	}
}

func TestDashboard666UsesRepositoryWatcherIdentity(t *testing.T) {
	m := marker(t, auth666Plan("authentic"))
	bad := marker(t, auth666Plan("reposted by a different commenter"))
	r1 := auth666Repo(t, "owner/first", "first[bot]", []github.Comment{auth666Comment("first[bot]", m, 10), auth666Comment("second[bot]", bad, 20)})
	r2 := auth666Repo(t, "owner/second", "second[bot]", []github.Comment{auth666Comment("second[bot]", m, 10), auth666Comment("first[bot]", bad, 20)})
	s := &Server{Repos: []*Repo{r1, r2}}
	for _, got := range auth666Snapshot(t, s).Issues {
		if got.Waiting == nil || got.Waiting.Name != "authentic" || got.SpendUSD != 2 || got.GateRuns != 1 {
			t.Errorf("%s used another repository's identity: %+v", got.Repo, got)
		}
	}
	for _, mode := range []string{"missing", "legacy", "malformed", "wrong repository", "stopped"} {
		t.Run(mode, func(t *testing.T) {
			r := auth666Repo(t, "owner/project", "factory[bot]", []github.Comment{auth666Comment("factory[bot]", m, 10)})
			switch mode {
			case "missing":
				if err := os.Remove(r.Status); err != nil {
					t.Fatal(err)
				}
			case "legacy":
				if err := os.WriteFile(r.Status, []byte(`{"repo":"owner/project","pid":1}`), 0600); err != nil {
					t.Fatal(err)
				}
			case "malformed":
				if err := os.WriteFile(r.Status, []byte(`{`), 0600); err != nil {
					t.Fatal(err)
				}
			case "wrong repository":
				auth666Status(t, r.Status, "owner/somewhere-else", "factory[bot]", os.Getpid(), "holder")
			case "stopped":
				auth666Status(t, r.Status, r.Name, "factory[bot]", 0, "holder")
			}
			got := auth666Snapshot(t, &Server{Repos: []*Repo{r}}).Issues[0]
			if mode == "stopped" {
				if got.Waiting == nil || got.Waiting.Name != "authentic" {
					t.Errorf("stopped status lost its known identity: %+v", got)
				}
			} else if got.Waiting != nil || got.SpendUSD != 0 || got.GateRuns != 0 {
				t.Errorf("%s status authorized marker state: %+v", mode, got)
			}
		})
	}
	// The lease's selected watcher supplies authority, not the first status file.
	work1, work2 := t.TempDir(), t.TempDir()
	r := auth666Repo(t, "owner/multiple", "unused[bot]", []github.Comment{auth666Comment("selected[bot]", m, 10), auth666Comment("first[bot]", bad, 20)})
	auth666Status(t, StatusPath(work1, r.Name), r.Name, "first[bot]", os.Getpid(), "first")
	auth666Status(t, StatusPath(work2, r.Name), r.Name, "selected[bot]", os.Getpid(), "selected")
	s = &Server{Repos: []*Repo{r}, Works: []string{work1, work2}}
	s.holding(r.Name, &Lease{Holder: "selected"})
	got := auth666Snapshot(t, s).Issues[0]
	if got.Waiting == nil || got.Waiting.Name != "authentic" || got.SpendUSD != 2 {
		t.Errorf("selected watcher did not supply marker identity: %+v", got)
	}
}

func TestDashboard666MergeChecksIgnoreRepostedMarkers(t *testing.T) {
	dir := t.TempDir()
	bin, calls := filepath.Join(dir, "gh"), filepath.Join(dir, "calls")
	quote := func(s string) string { return "'" + strings.ReplaceAll(s, "'", "'\"'\"'") + "'" }
	script := `#!/bin/sh
if [ "$1" = auth ]; then exit 1; fi
if [ "$#" -ne 7 ] || [ "$1" != api ] || [ "$2" != --include ] || [ "$3" != -X ] || [ "$4" != GET ] || [ "$5" != -H ] || [ "$6" != 'Accept: application/vnd.github+json' ]; then exit 90; fi
printf '%s\n' "$7" >> ` + quote(calls) + `
case "$7" in
repos/owner/project/pulls/47) printf '%s\n' '{"number":47,"merged":true,"head":{"sha":"authentic-head"}}' ;;
repos/owner/project/pulls/99) printf '%s\n' '{"number":99,"merged":true,"head":{"sha":"reposted-head"}}' ;;
repos/owner/project/commits/*/check-runs*) printf '%s\n' '{"check_runs":[{"name":"invariant/gate","status":"completed","conclusion":"success"}]}' ;;
*) exit 91 ;;
esac
`
	if err := os.WriteFile(bin, []byte(script), 0700); err != nil {
		t.Fatal(err)
	}
	comments := []github.Comment{auth666Comment("factory[bot]", marker(t, factory.Marker{Kind: factory.KindMerged, PR: 47}), 10), auth666Comment("person", marker(t, factory.Marker{Kind: factory.KindMerged, PR: 99}), 20)}
	for _, self := range []string{"factory[bot]", ""} {
		if err := os.WriteFile(calls, nil, 0600); err != nil {
			t.Fatal(err)
		}
		r := auth666Repo(t, "owner/project", self, comments)
		r.GitHub = github.Client{Repo: r.Name, GH: bin}
		r.src.issues[0].State = "closed"
		r.src.issues[0].Labels = []github.Label{{Name: factory.LabelMerged}}
		s := &Server{Repos: []*Repo{r}}
		s.checkMerges(t.Context(), r)
		b, err := os.ReadFile(calls)
		if err != nil {
			t.Fatal(err)
		}
		got := string(b)
		if self == "" {
			if got != "" {
				t.Errorf("unknown identity triggered merge reads: %s", got)
			}
		} else {
			if !strings.Contains(got, "/pulls/47\n") || !strings.Contains(got, "/commits/authentic-head/check-runs") || strings.Contains(got, "/pulls/99") || strings.Contains(got, "reposted-head") {
				t.Errorf("merge checks followed the wrong marker: %s", got)
			}
			if got := auth666Snapshot(t, s).Totals; got.Merged != 1 || got.MergesChecked != 1 || got.BadMerges != 0 {
				t.Errorf("authentic merge lost its checked totals: %+v", got)
			}
		}
	}
}

// Reuse #648's real proposal/checking path and its offline TLC process double.
// The only attacker-controlled change in the replay is the comment author.
func auth666Comparison(t *testing.T) *formalize.Proposal {
	t.Helper()
	tc, _ := reader603Tools(t)
	ws := t.TempDir()
	reader603Workspace(t, ws)
	old, _, err := formalize.Check(t.Context(), ws, tc)
	if err != nil {
		t.Fatal(err)
	}
	a := comparison648Agent{run: func(_ context.Context, j synth.Job) (synth.Usage, error) {
		reader603Workspace(t, j.Workspace)
		reader603Write(t, filepath.Join(j.Workspace, "view.json"), strings.ReplaceAll(reader603View, "Working", "Revised working"))
		reader603Write(t, filepath.Join(j.Workspace, "proposal.json"), strings.ReplaceAll(reader603Draft, `"Limit":"2"`, `"Limit":"3"`))
		return synth.Usage{}, nil
	}}
	r, err := (formalize.Formalizer{Backend: a, Toolchain: tc}).Formalize(t.Context(), formalize.Request{Repo: "owner/project", Issue: 666, Previous: old}, t.TempDir())
	if err != nil || r == nil || r.Problem != "" || r.Proposal == nil {
		t.Fatalf("checked comparison: %+v, %v", r, err)
	}
	if r.Proposal.Reader == nil || r.Proposal.Reader.Comparison == nil {
		t.Fatal("fixture has no checked comparison")
	}
	return r.Proposal
}

func auth666NoPages(t *testing.T, s *Server, presentations ...*ReaderPresentation) {
	t.Helper()
	for _, p := range presentations {
		for _, url := range []string{p.Page, p.SVG} {
			if url == "" {
				t.Fatal("fixture lacks a reader URL")
			}
			if w := reader631GET(s, "GET", url, ""); w.Code != http.StatusNotFound {
				t.Errorf("untrusted reader page %s returned HTTP %d, want 404", url, w.Code)
			}
		}
	}
}

func TestDashboard666RepostedComparisonCannotPublishReaderPages(t *testing.T) {
	p := auth666Comparison(t)
	body := marker(t, factory.Marker{Kind: factory.KindProposal, Proposal: p})
	r := auth666Repo(t, "owner/project", "factory[bot]", []github.Comment{auth666Comment("factory[bot]", body, 10)})
	s := &Server{Repos: []*Repo{r}, Cache: t.TempDir()}
	waiting := auth666Snapshot(t, s).Issues[0].Waiting
	if waiting == nil || waiting.Reader == nil {
		t.Fatal("authentic proposal lost its reader")
	}
	pres := waiting.Reader
	comparison648Page(t, s, pres, []string{"Working", "Revised working", "added", "removed"})
	cold := &Server{Cache: s.Cache, Repos: []*Repo{{Name: r.Name, Status: r.Status}}}
	cold.loadSnapshot()
	comparison648Page(t, cold, pres, []string{"Revised working"})
	for _, tc := range []struct{ author, self string }{{"person", "factory[bot]"}, {"other[bot]", "factory[bot]"}, {"factory[bot]", ""}} {
		other := auth666Repo(t, r.Name, tc.self, []github.Comment{auth666Comment(tc.author, body, 10)})
		forged := &Server{Repos: []*Repo{other}, Cache: t.TempDir()}
		if got := auth666Snapshot(t, forged).Issues[0]; got.Waiting != nil {
			t.Errorf("repost by %s with self %q produced a waiting card", tc.author, tc.self)
		}
		auth666NoPages(t, forged, pres)
		restarted := &Server{Cache: forged.Cache, Repos: []*Repo{{Name: other.Name, Status: other.Status}}}
		restarted.loadSnapshot()
		auth666NoPages(t, restarted, pres)
	}
	// Even an authenticated saved card cannot authorize itself if local identity
	// is absent or has changed before a restart.
	for _, self := range []string{"", "replacement[bot]"} {
		auth666Status(t, r.Status, r.Name, self, os.Getpid(), "holder")
		changed := &Server{Cache: s.Cache, Repos: []*Repo{{Name: r.Name, Status: r.Status}}}
		changed.loadSnapshot()
		auth666NoPages(t, changed, pres)
	}
}

func TestDashboard666RepostedOptionsCannotPublishReaderPages(t *testing.T) {
	tc, _ := reader603Tools(t)
	ws := t.TempDir()
	preview639Write(t, ws, preview639Draft(t, 1, nil))
	p := preview639Checked(t, ws, tc)
	body := marker(t, factory.Marker{Kind: factory.KindForks, Forks: p.Forks, Proposal: p})
	r := auth666Repo(t, "owner/project", "factory[bot]", []github.Comment{auth666Comment("factory[bot]", body, 10)})
	s := &Server{Repos: []*Repo{r}, Cache: t.TempDir()}
	snap := auth666Snapshot(t, s)
	if snap.Issues[0].Waiting == nil {
		t.Fatal("authentic alternatives disappeared")
	}
	var presentations []*ReaderPresentation
	for _, q := range snap.Issues[0].Waiting.Forks {
		for _, o := range q.Options {
			if o.Reader == nil || o.Reader.Status != "chart" {
				t.Fatalf("authentic option has no chart: %+v", o)
			}
			for _, url := range []string{o.Reader.Page, o.Reader.SVG} {
				if w := reader631GET(s, "GET", url, ""); w.Code != http.StatusOK {
					t.Fatalf("authentic option HTTP %d", w.Code)
				}
			}
			presentations = append(presentations, o.Reader)
		}
	}
	if len(presentations) != 2 {
		t.Fatalf("fixture has %d alternatives, want 2", len(presentations))
	}
	for _, self := range []string{"factory[bot]", ""} {
		r := auth666Repo(t, "owner/project", self, []github.Comment{auth666Comment("person", body, 10)})
		forged := &Server{Repos: []*Repo{r}}
		if got := auth666Snapshot(t, forged).Issues[0]; got.Waiting != nil {
			t.Errorf("reposted options created a waiting card for self %q", self)
		}
		auth666NoPages(t, forged, presentations...)
	}
}

func TestDashboard666LegacyCacheCannotRestoreMarkerAuthority(t *testing.T) {
	p := auth666Comparison(t)
	for _, self := range []string{"factory[bot]", ""} {
		r := auth666Repo(t, "owner/project", self, nil)
		cache := t.TempDir()
		old := &Server{Repos: []*Repo{r}, Cache: cache}
		// Construct the exact old cache shape, without any newly added policy or
		// author provenance. The payload itself is fully checked and consistent.
		pres := old.keepComparison(comparisonEvidence{Format: comparisonFormat, Repo: r.Name, Issue: 666, Proposal: p})
		legacy := map[string]any{"repo": r.Name, "issues": []any{map[string]any{
			"repo": r.Name, "number": 666, "title": "reposted proposal", "open": true, "stage": StageRatifying,
			"waiting": map[string]any{"kind": factory.KindProposal, "proposal": p, "reader": pres},
		}}}
		b, err := json.Marshal(legacy)
		if err != nil {
			t.Fatal(err)
		}
		gz, err := gzipped(b)
		if err != nil {
			t.Fatal(err)
		}
		old.saveSnapshot(gz)
		cold := &Server{Repos: []*Repo{{Name: r.Name, Status: r.Status}}, Cache: cache}
		cold.loadSnapshot()
		auth666NoPages(t, cold, pres)
		res := reader631GET(cold, "GET", "/api/state.json", "")
		if res.Code == http.StatusOK {
			var got Snapshot
			if err := json.Unmarshal(res.Body.Bytes(), &got); err != nil {
				t.Fatal(err)
			}
			for _, is := range got.Issues {
				if is.Waiting != nil {
					t.Errorf("legacy cache restored a waiting card with self %q: %s", self, res.Body.String())
				}
			}
		} else if res.Code != http.StatusServiceUnavailable {
			t.Error(fmt.Sprintf("unexpected startup response: HTTP %d", res.Code))
		}
	}
}
